import sys
import os
import xml.etree.ElementTree as ET
from threading import Thread, Semaphore
from queue import Queue
import subprocess

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        if root.tag != 'jobs':
            return None
        max_parallel = root.attrib.get('max_parallel')
        log_file = root.attrib.get('log_file')
        if not max_parallel or not log_file:
            return None
        try:
            max_parallel = int(max_parallel)
            if max_parallel <= 0:
                return None
        except ValueError:
            return None
        jobs = []
        for job in root.findall('job'):
            job_id = job.attrib.get('id')
            job_cmd = job.attrib.get('command')
            if not job_id or not job_cmd:
                return None
            jobs.append((job_id, job_cmd))
        return (max_parallel, log_file, jobs)
    except Exception:
        return None

def log_job(log_file, job_id, start_action):
    with open(log_file, 'a') as f:
        if start_action:
            f.write(f"START {job_id}\n")
        else:
            f.write(f"END {job_id} exit=0\n")

def run_job(job_id, job_cmd, log_file, result_queue):
    try:
        process = subprocess.Popen(job_cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()
        exit_code = process.returncode
        with open(log_file, 'a') as f:
            f.write(f"END {job_id} exit={exit_code}\n")
        result_queue.put((job_id, exit_code))
    except Exception as e:
        with open(log_file, 'a') as f:
            f.write(f"END {job_id} exit=1\n")
        result_queue.put((job_id, 1))

def job_runner(max_parallel, log_file, jobs):
    semaphore = Semaphore(max_parallel)
    result_queue = Queue()
    threads = []

    for job_id, job_cmd in jobs:
        semaphore.acquire()
        thread = Thread(target=run_job, args=(job_id, job_cmd, log_file, result_queue))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    completed = 0
    failed = 0
    while not result_queue.empty():
        job_id, exit_code = result_queue.get()
        if exit_code == 0:
            completed += 1
        else:
            failed += 1

    print(f"completed={completed} failed={failed}")
    sys.exit(0 if failed == 0 else 1)

def main():
    if len(sys.argv) != 2:
        print("config error", file=sys.stderr)
        sys.exit(2)

    xml_path = sys.argv[1]
    result = parse_xml(xml_path)
    if not result:
        print("config error", file=sys.stderr)
        sys.exit(2)

    max_parallel, log_file, jobs = result
    log_job(log_file, "root", False)  # Ensure log file exists

    job_runner(max_parallel, log_file, jobs)

if __name__ == "__main__":
    main()
